<script setup lang="ts">import{computed,ref}from'vue';import type{BenchmarkReport}from'@smart-factory/benchmark';import MetricCard from'../components/MetricCard.vue';import{platform}from'../platform';import{loadRuntimeConfig}from'../runtime-config';import{downloadBenchmarkReport,runBackendPingBenchmark,runSyntheticBenchmark}from'../services/benchmark';const running=ref(false);const progress=ref({done:0,total:0});const report=ref<BenchmarkReport|null>(null);const error=ref<string|null>(null);const summary=computed(()=>report.value?.summary);const testType=computed(()=>report.value?.mode==='SYNTHETIC'?'本机计算':'后端往返');async function run(mode:'synthetic'|'http'){running.value=true;error.value=null;report.value=null;try{const c=await loadRuntimeConfig();const cb=(done:number,total:number)=>progress.value={done,total};report.value=mode==='synthetic'?await runSyntheticBenchmark(platform,c,cb):await runBackendPingBenchmark(platform,c,cb);}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{running.value=false;}}</script>
<template><section class="operator-page"><p class="eyebrow">性能监测</p><h1>通信与响应性能</h1><p class="lead">查看当前运行环境的请求延迟、成功率和吞吐情况。</p><div class="benchmark-actions"><button class="primary-button" :disabled="running" @click="run('http')">测量后端响应</button><button class="secondary-button" :disabled="running" @click="run('synthetic')">测量本机计算</button><button v-if="report" class="secondary-button" @click="downloadBenchmarkReport(report)">导出结果</button><span v-if="running">{{progress.done}} / {{progress.total}}</span></div><p v-if="error" class="error">{{error}}</p><template v-if="report&&summary"><div class="metric-row"><MetricCard label="测量类型" :value="testType" detail="当前运行环境"/><MetricCard label="P95" :value="summary.p95Ms===null?'—':`${summary.p95Ms} ms`" :detail="`P50 ${summary.p50Ms??'—'} ms`"/><MetricCard label="P99" :value="summary.p99Ms===null?'—':`${summary.p99Ms} ms`" :detail="`最大 ${summary.maxMs??'—'} ms`"/><MetricCard label="成功率" :value="`${(summary.successRate*100).toFixed(1)}%`" :detail="`${summary.errors} 异常 / ${summary.total}`"/></div><div class="two-col"><div class="panel"><h2>运行环境</h2><pre>{{JSON.stringify(report.environment,null,2)}}</pre></div><div class="panel"><h2>性能结果</h2><p>抖动：{{summary.jitterStdDevMs??'—'}} ms</p><p>吞吐：{{summary.throughputPerSec}} 次/秒</p><p>耗时：{{summary.durationMs}} ms</p></div></div></template></section></template>
